import{_ as s,o as n,c as t,a6 as a}from"./chunks/framework.BrkgobfX.js";const h=JSON.parse('{"title":"nginx 如何处理请求","description":"虚拟服务器选择的两步、default_server 的真实含义、server_name 匹配的四级优先级。","frontmatter":{"title":"nginx 如何处理请求","description":"虚拟服务器选择的两步、default_server 的真实含义、server_name 匹配的四级优先级。","source":"https://daiw.org/manual/nginx/request-processing"},"headers":[],"relativePath":"manual/tools/nginx/request-processing.md","filePath":"manual/tools/nginx/request-processing.md"}'),r={name:"manual/tools/nginx/request-processing.md"};function o(l,e,i,d,p,c){return n(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="nginx-如何处理请求" tabindex="-1">nginx 如何处理请求 <a class="header-anchor" href="#nginx-如何处理请求" aria-label="Permalink to &quot;nginx 如何处理请求&quot;">​</a></h1><p>搞清一个请求<strong>落到哪个 server</strong>，是排查「配置没生效」的第一步。</p><h2 id="两步选择" tabindex="-1">两步选择 <a class="header-anchor" href="#两步选择" aria-label="Permalink to &quot;两步选择&quot;">​</a></h2><p>官方 <a href="https://nginx.org/en/docs/http/request_processing.html" target="_blank" rel="noreferrer">How nginx processes a request</a> 描述的顺序：</p><blockquote><p>nginx first tests the <strong>IP address and port</strong> of the request against the <code>listen</code> directives of the <code>server</code> blocks. It then tests the <strong>&quot;Host&quot; header field</strong> of the request against the <code>server_name</code> entries of the <code>server</code> blocks <strong>that matched the IP address and port</strong>.</p></blockquote><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第 1 步：按 listen 匹配 IP:端口   → 得到候选 server 集合</span></span>
<span class="line"><span>第 2 步：在候选集合内按 Host 匹配 server_name</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>顺序不可颠倒</strong>：<code>server_name</code> 只在<strong>已经匹配上 listen</strong> 的 server 之间比较。一个 <code>server_name example.com</code> 但 <code>listen 8080</code> 的块，永远不会接到 80 端口的请求，哪怕 Host 完全对得上。</p><h2 id="default-server" tabindex="-1">default_server <a class="header-anchor" href="#default-server" aria-label="Permalink to &quot;default\\_server&quot;">​</a></h2><p>Host 匹配不上任何 <code>server_name</code> 时怎么办：</p><blockquote><p>If its value does not match any server name, or <strong>the request does not contain this header field at all</strong>, then nginx will route the request to the <strong>default server</strong> for this port.</p></blockquote><p>默认服务器的确定方式：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server {</span></span>
<span class="line"><span>    listen      80 default_server;</span></span>
<span class="line"><span>    server_name example.net www.example.net;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>没有显式标注时：</p><blockquote><p>the default server is <strong>the first one</strong> — which is nginx&#39;s standard default behaviour.</p></blockquote><p><strong>该端口上第一个出现的 server 块</strong>就是默认服务器。</p><p>官方特别强调的一句：</p><blockquote><p>Note that the default server is a property of the <strong>listen port</strong> and not of the server name.</p></blockquote><p><strong>默认服务器是「端口」的属性，不是「名字」的属性。</strong> 所以 <code>default_server</code> 写在 <code>listen</code> 上而不是 <code>server_name</code> 上，而且<strong>每个端口各有一个</strong>默认服务器——80 和 443 的默认服务器是相互独立的。</p><p>这条经常被误解成「default_server 是兜底站点」。准确说法是：<strong>它是该端口上 Host 匹配失败时的接管者</strong>。</p><h2 id="拒绝无-host-的请求" tabindex="-1">拒绝无 Host 的请求 <a class="header-anchor" href="#拒绝无-host-的请求" aria-label="Permalink to &quot;拒绝无 Host 的请求&quot;">​</a></h2><p>官方给的做法：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server {</span></span>
<span class="line"><span>    listen      80;</span></span>
<span class="line"><span>    server_name &quot;&quot;;</span></span>
<span class="line"><span>    return      444;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><blockquote><p>Here, the server name is set to an <strong>empty string</strong> that will match requests <strong>without the &quot;Host&quot; header field</strong>, and a special nginx&#39;s non-standard code <strong>444</strong> is returned that closes the connection.</p></blockquote><p>两个知识点：</p><ul><li><strong><code>server_name &quot;&quot;</code></strong> 专门匹配「没有 Host 头」的请求。</li><li><strong><code>444</code></strong> 是 nginx 私有的非标准码：<strong>不返回任何响应，直接关闭连接</strong>。它不在 <a href="https://daiw.org/manual/http11/status-codes" target="_blank" rel="noreferrer">HTTP 状态码</a>注册表里，只在 nginx 内部有意义。</li></ul><p><a href="https://daiw.org/manual/http11/request-line" target="_blank" rel="noreferrer">HTTP/1.1 规定</a> <code>Host</code> 必需且唯一，缺失应返回 <code>400</code>。用 <code>444</code> 直接断连是更省资源的做法——对扫描器不必浪费一个响应。</p><h2 id="server-name-的匹配优先级" tabindex="-1">server_name 的匹配优先级 <a class="header-anchor" href="#server-name-的匹配优先级" aria-label="Permalink to &quot;server\\_name 的匹配优先级&quot;">​</a></h2><p>多个 server 都可能匹配时，官方给了<strong>严格的四级顺序</strong>：</p><blockquote><p>The search is performed in the following <strong>order of priority</strong> and <strong>terminates on the first matching variant</strong>:</p><ol><li>the <strong>exact</strong> name</li><li>the <strong>longest wildcard name starting with an asterisk</strong>, e.g. <code>*.example.com</code></li><li>the <strong>longest wildcard name ending with an asterisk</strong>, e.g. <code>mail.*</code></li><li>the <strong>first matching regular expression</strong> (in order of appearance in the configuration file)</li></ol></blockquote><table tabindex="0"><thead><tr><th>优先级</th><th>形式</th><th>例子</th></tr></thead><tbody><tr><td>1</td><td>精确名</td><td><code>www.example.com</code></td></tr><tr><td>2</td><td><strong>前置</strong>通配，取<strong>最长</strong>匹配</td><td><code>*.example.com</code></td></tr><tr><td>3</td><td><strong>后置</strong>通配，取<strong>最长</strong>匹配</td><td><code>mail.*</code></td></tr><tr><td>4</td><td>正则，取<strong>配置中第一个</strong>匹配</td><td><code>~^www\\d+\\.example\\.com$</code></td></tr></tbody></table><p>三个易错点：</p><ul><li><strong>通配符只能在开头或结尾</strong>，且必须以 <code>.</code> 分隔。<code>www.*.com</code> 非法。</li><li>通配之间比<strong>长度</strong>，正则之间比<strong>出现顺序</strong>——两套不同的裁决方式。</li><li><strong>精确名永远赢</strong>，哪怕正则写在前面。</li></ul><p>不要把这四级顺序与 <a href="/Front2Full/manual/tools/nginx/location">location 的匹配规则</a>混为一谈——两者规则完全不同，是最常见的记忆混淆。<code>server_name</code> 是「先精确、再通配比长度、最后正则比顺序」；location 是「前缀取最长并记住、再按顺序试正则、正则命中即用」。</p><h2 id="完整流程" tabindex="-1">完整流程 <a class="header-anchor" href="#完整流程" aria-label="Permalink to &quot;完整流程&quot;">​</a></h2><p>图表加载中…</p><h2 id="listen-的匹配精度" tabindex="-1">listen 的匹配精度 <a class="header-anchor" href="#listen-的匹配精度" aria-label="Permalink to &quot;listen 的匹配精度&quot;">​</a></h2><p><code>listen</code> 本身也有精确度之分，nginx 优先选<strong>更具体</strong>的：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server { listen 192.0.2.1:80; server_name example.com; }  # 具体 IP</span></span>
<span class="line"><span>server { listen 80;           server_name example.com; }  # 所有 IP</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>发往 <code>192.0.2.1:80</code> 的请求命中第一个——<strong>绑定具体 IP 比绑定通配地址更精确</strong>。</p><h2 id="调试手法" tabindex="-1">调试手法 <a class="header-anchor" href="#调试手法" aria-label="Permalink to &quot;调试手法&quot;">​</a></h2><p>不确定请求落到哪个 server 时，给每个 server 加一个标记头：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server {</span></span>
<span class="line"><span>    server_name example.com;</span></span>
<span class="line"><span>    add_header X-Debug-Server &quot;example.com-block&quot; always;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>注意加 <code>always</code>——<code>add_header</code> 默认只对 <code>200</code>、<code>201</code>、<code>204</code>、<code>206</code>、<code>301</code>、<code>302</code>、<code>303</code>、<code>304</code>、<code>307</code>、<code>308</code> 生效，<strong>错误响应不会带上这个头</strong>，而排查时恰恰常是错误响应。相关的<a href="/Front2Full/manual/tools/nginx/contexts">继承覆盖问题</a>也要留意。</p><p>下一篇：<a href="/Front2Full/manual/tools/nginx/core-module">核心模块指令</a>。</p>`,44)])])}const u=s(r,[["render",o]]);export{h as __pageData,u as default};
